  x <- read.csv(path, check.names = FALSE); p <- vapply(x$path, resolve, character(1))
  observed <- vapply(p, sha, character(1)); bytes <- file.info(p)$size
  stopifnot(nrow(x) == specs$rows[i], all(observed == x$sha256), all(bytes == x$bytes), all(Sys.readlink(p) == ""))
  data.frame(manifest=specs$path[i],path=x$path,expected_sha256=x$sha256,observed_sha256=unname(observed),expected_bytes=x$bytes,observed_bytes=bytes)
})
